5.2 Analysis 1: Event Volume Overview


Code
```{r}
#| eval: false

# ── Identical to dplyr — but DuckDB executes it ───────────────────────────────
event_summary &lt;- ga4_events |&gt;
  group_by(event_name) |&gt;
  summarise(
    total_events = n(),
    unique_users = n_distinct(user_pseudo_id),
    unique_days = n_distinct(event_date),
    events_per_day = round(total_events / unique_days, 1),
    .groups = "drop"
  ) |&gt;
  arrange(desc(total_events))

# Result is already a tibble — no collect() needed
event_summary |&gt;
  gt() |&gt;
  tab_header(
    title = "GA4 Event Summary",
    subtitle = "Computed by DuckDB via duckplyr"
  ) |&gt;
  fmt_number(columns = c(total_events, unique_users), decimals = 0) |&gt;
  fmt_number(columns = events_per_day, decimals = 1) |&gt;
  cols_label(
    event_name = "Event",
    total_events = "Total Events",
    unique_users = "Unique Users",
    unique_days = "Days",
    events_per_day = "Events/Day"
  ) |&gt;
  opt_stylize(style = 1)
```

5.3 Analysis 2: Traffic Source Performance


Code
```{r}
#| eval: false

# ── Join sessions with purchase events ────────────────────────────────────────
# duckplyr handles joins the same as dplyr
purchasers &lt;- ga4_events |&gt;
  filter(event_name == "purchase") |&gt;
  distinct(user_pseudo_id) |&gt;
  mutate(purchased = TRUE)

traffic_performance &lt;- ga4_sessions |&gt;
  mutate(
    channel = case_when(
      is.na(traffic_source_medium) |
        traffic_source_medium == "(none)" ~ "Direct",
      traffic_source_medium == "organic" ~ "Organic Search",
      traffic_source_medium %in% c("cpc", "ppc") ~ "Paid Search",
      str_detect(traffic_source_medium, "email") ~ "Email",
      str_detect(traffic_source_medium, "social") ~ "Social",
      TRUE ~ str_to_title(traffic_source_medium)
    )
  ) |&gt;
  group_by(channel) |&gt;
  summarise(
    sessions = n(),
    unique_users = n_distinct(user_pseudo_id),
    .groups = "drop"
  ) |&gt;
  left_join(
    ga4_sessions |&gt;
      mutate(
        channel = case_when(
          is.na(traffic_source_medium) |
            traffic_source_medium == "(none)" ~ "Direct",
          traffic_source_medium == "organic" ~ "Organic Search",
          traffic_source_medium %in% c("cpc", "ppc") ~ "Paid Search",
          str_detect(traffic_source_medium, "email") ~ "Email",
          str_detect(traffic_source_medium, "social") ~ "Social",
          TRUE ~ str_to_title(traffic_source_medium)
        )
      ) |&gt;
      select(user_pseudo_id, channel) |&gt;
      left_join(purchasers, by = "user_pseudo_id") |&gt;
      group_by(channel) |&gt;
      summarise(
        converters = sum(as.integer(!is.na(purchased)), na.rm = TRUE),
        .groups = "drop"
      ),
    by = "channel"
  ) |&gt;
  mutate(
    cvr = converters / unique_users,
    sessions_pct = sessions / sum(sessions)
  ) |&gt;
  arrange(desc(sessions))

traffic_performance |&gt;
  gt() |&gt;
  tab_header(title = "Traffic Channel Performance") |&gt;
  fmt_number(columns = c(sessions, unique_users, converters), decimals = 0) |&gt;
  fmt_percent(columns = c(cvr, sessions_pct), decimals = 1) |&gt;
  cols_label(
    channel = "Channel",
    sessions = "Sessions",
    unique_users = "Users",
    converters = "Buyers",
    cvr = "CVR",
    sessions_pct = "% of Sessions"
  ) |&gt;
  data_color(
    columns = cvr,
    method = "numeric",
    palette = c("#ffffff", "#43a04740")
  ) |&gt;
  opt_stylize(style = 1)
```

