    write_dataset(
      path = "data/ga4_params_partitioned",
      format = "parquet",
      partitioning = c("year", "month"),
      compression = "snappy"
    )

  cli::cli_alert_success(
    "Params partitioned dataset written to data/ga4_params_partitioned/"
  )
}
```



