```{r}
#| label: download-summary
#| eval: true
#| cache: false

cli::cli_h1("Download Summary")

if (exists("download_log") && length(download_log) &gt; 0) {
  # &&: short-circuit evaluation
  # ── Build log data frame ──────────────────────────────────────────────────
  log_df &lt;- download_log |&gt;
    imap(\(x, nm) {
      # imap_df() iterates over the named list, where x is the value (list with status and rows) and nm is the name (table name)
      tibble(
        table = nm,
        status = x$status,
        rows = x$rows %||% NA_integer_ # %||% is a null coalescing operator that returns the left-hand side if it's not NULL, otherwise it returns the right-hand side. This ensures that if x$rows is NULL (e.g., in case of an error), it will be recorded as NA_integer_ instead of causing an error when trying to access it.
      )
    }) |&gt;
    list_rbind() |&gt; # ← replaces imap_dfr
    mutate(
      date = ymd(str_extract(table, "\\d{8}")),
      month_label = glue("{month.abb[month(date)]} {year(date)}")
    )

  # ── Status summary ────────────────────────────────────────────────────────
  cat("Status Summary:\n")
  log_df |&gt;
    count(status, name = "tables") |&gt;
    knitr::kable(col.names = c("Status", "Tables"))

  # ── Monthly summary ───────────────────────────────────────────────────────
  cat("\nRows by Month:\n")
  log_df |&gt;
    filter(status == "success") |&gt;
    group_by(month_label) |&gt;
    summarise(
      days_downloaded = n(),
      total_rows = sum(rows, na.rm = TRUE),
      avg_rows_per_day = round(mean(rows, na.rm = TRUE)),
      .groups = "drop"
    ) |&gt;
    mutate(
      total_rows = scales::comma(total_rows),
      avg_rows_per_day = scales::comma(avg_rows_per_day)
    ) |&gt;
    knitr::kable(
      col.names = c("Month", "Days", "Total Rows", "Avg Rows/Day")
    )

  # ── Flag any failures ─────────────────────────────────────────────────────
  failed &lt;- log_df |&gt; filter(status == "error")

  if (nrow(failed) &gt; 0) {
    cli::cli_alert_danger("{nrow(failed)} tables failed:")
    failed |&gt;
      select(table, status) |&gt;
      print()
    cli::cli_alert_info(
      "Re-run the download loop — it skips successful days automatically."
    )
  } else {
    cli::cli_alert_success("All tables downloaded successfully!")
  }
}
